  /* gen số nhiều = 0 với nguyên âm chèn cho -ка/-ня/-о… */
  function genPlZero(stem, w){
    // stem: thân không có đuôi (ví dụ 'девушк' cho девушка; 'окн' cho окно)
    const n = stem.length; if (n < 2) return stem;
    const c1 = stem[n - 2], c2 = stem[n - 1];
    if (isV(c1)) { // йка → ек; статья/семья (ь) → ей xử lý riêng
      if (c1 === 'й' ) return stem.slice(0, -2) + 'е' + c2; // копейка → копеек; лейка → леек
      return stem;
    }
    if (c1 === 'ь'){ return stem.slice(0, -2) + 'е' + c2; } // письмо → писем; тюрьма → тюрем; серьга → серёг(≈)
    if (c1 === 'й'){ return stem.slice(0, -2) + 'е' + c2; }
    if (c2 === 'к'){
      if (HUSH.indexOf(c1) >= 0 || 'ц'.indexOf(c1) >= 0) return stem.slice(0, -1) + 'ек';
      return stem.slice(0, -1) + 'ок';
    }
    if (c2 === 'н' || c2 === 'л' || c2 === 'р' || c2 === 'м'){
      if (c1 === 'ж' || c1 === 'ш' || c1 === 'ч' || c1 === 'щ' || c1 === 'ц' || c1 === 'к' || c1 === 'г' || c1 === 'х') return stem.slice(0, -1) + 'е' + c2; // окно → окон (к→о!) xử lý: после к/г/х → о
      return stem.slice(0, -1) + 'е' + c2;
    }
    if (c2 === 'ц'){ return stem.slice(0, -1) + 'ец'; } // сердце → сердец, кольцо → колец
    return stem;
  }
  function genPlZeroFix(stem){
    const n = stem.length; if (n < 2) return genPlZero(stem);
    const c1 = stem[n - 2], c2 = stem[n - 1];
    if (!isV(c1) && c1 !== 'ь' && c1 !== 'й' && (c2 === 'н' || c2 === 'л' || c2 === 'р' || c2 === 'м') && (c1 === 'к' || c1 === 'г' || c1 === 'х')) return stem.slice(0, -1) + 'о' + c2; // окно → окон, стекло → стёкол(≈стекол)
    return genPlZero(stem);
  }

  /* Rụng nguyên âm lướt trong thân giống đực */
  function dropFleeting(w){
    if (NOUN_IRR[w]) return null;
    if (NO_DROP.has(w)) return w;
    if (w.length < 4) return w;
    const n = w.length, c = w[n - 1], v = w[n - 2], b = w[n - 3];
    if (c === 'к' && v === 'о' && !isV(b) && vowels(w) >= 2) return w.slice(0, -2) + 'к';        // кусок → куск-
    if (c === 'к' && v === 'ё' && !isV(b)) return w.slice(0, -2) + 'ьк';                          // денёк → деньк-
    if (c === 'к' && v === 'е' && HUSH.indexOf(b) >= 0) return w.slice(0, -2) + 'к';               // кусочек → кусочк-
    if (c === 'ц' && v === 'е' && !isV(b) && vowels(w) >= 2){                                       // отец → отц-, немец → немц-
      if (b === 'й') return w.slice(0, -3) + 'йц';
      return w.slice(0, -2) + 'ц';
    }
    if (c === 'ц' && v === 'е' && b === 'я') return w;                                              // заяц xử lý riêng
    if (DROP_EN.has(w)){
      if (endsWith(w, 'ень')) return w.slice(0, -3) + 'н';                                         // день → дн-
      if (endsWith(w, 'ель')) return w.slice(0, -3) + 'л';                                         // кашель → кашл-
      if (endsWith(w, 'оть')) return w.slice(0, -3) + 'т';                                         // ноготь → ногт-
      if (endsWith(w, 'ер')) return w.slice(0, -2) + 'р';                                          // ветер → ветр-
      if (endsWith(w, 'ёр') || endsWith(w, 'ёл')) return w.slice(0, -2) + w.slice(-1);            // ковёр → ковр-, орёл → орл-
      if (endsWith(w, 'ол') || endsWith(w, 'ел')) return w.slice(0, -2) + w.slice(-1);            // угол → угл-, узел → узл-
      if (endsWith(w, 'ец')) return w.slice(0, -2) + 'ц';
      return w.slice(0, -2) + w.slice(-1);                                                         // сон → сн-, лоб → лб-
    }
    return w;
  }

  /* Có giữ trọng âm ở các dạng không? (giống đực đa âm tiết trọng âm không ở cuối; giống cái/trung trọng âm ở thân) */
  function stableStress(lemma, g){
    const idx = stressIdx(lemma), nv = vowels(lemma);
    if (idx < 0) return false;
    const w = strip(lemma);
    if (g === 'm' && !endsWith(w, 'а', 'я')){ return nv >= 2 && idx < nv - 1; }
    if (g === 'f' || (g === 'm' && endsWith(w, 'а', 'я'))){ return idx < nv - 1; } // trọng âm không ở đuôi -а
    if (g === 'n'){ return endsWith(w, 'ие', 'ье', 'ство', 'ние', 'тие') || (nv >= 3 && idx < nv - 1 && !NEUT_FIXED.has(w)) ; }
    return false;
  }

  /* ===== BIẾN CÁCH DANH TỪ ===== */
  function noun(lemma, opts){
    opts = opts || {};
    const raw = strip(lemma).toLowerCase();
    const info = nounInfo(lemma, opts.pos, opts.vi);
    const g = opts.gender || info.g, anim = opts.animate != null ? opts.animate : info.anim;
    const notes = [];
    const res = { lemma, gender:g, animate:anim, sg:null, pl:null, notes, indecl:false };
    if (NOUN_IRR[raw]){
      const f = NOUN_IRR[raw];
      const mk = a => a[0] === '-' ? null : { nom:a[0], gen:a[1], dat:a[2], acc:a[3], ins:a[4], pre:a[5] };
      res.sg = mk(f.slice(0, 6)); res.pl = mk(f.slice(6)); res.irregular = true;
      if (!res.sg) res.pluralOnly = true;
      return res;
    }
    if (info.indecl || opts.indecl){
      res.indecl = true;
      const s = { nom:lemma, gen:lemma, dat:lemma, acc:lemma, ins:lemma, pre:lemma };
      res.sg = s; res.pl = Object.assign({}, s); notes.push('Danh từ bất biến: giữ nguyên ở mọi cách và số.');
      return res;
    }
    const w = raw;
    const keepS = stableStress(lemma, g);
    const K = f => keepS ? keep(lemma, f) : f;  // giữ trọng âm nếu ổn định
    const hushEnd = HUSH.indexOf(last(w)) >= 0;
    let sg = {}, pl = {};
    const stressOnEnd = vowels(lemma) === 1 || (stressIdx(lemma) === vowels(lemma) - 1 && vowels(lemma) >= 1); // trọng âm ở nguyên âm cuối
    if (info.pluralOnly){
      // số nhiều: nom = lemma; gen: -ов / -ей / 0
      const st = w.replace(/[ыи]$/, '');
      let gen;
      if (w.endsWith('а')) gen = w.slice(0, -1);
      else if (w.endsWith('и') && (last(st) === 'ь' || HUSH.indexOf(last(st)) >= 0 || /[тдлнр]$/.test(st))) gen = st.replace(/ь$/, '') + 'ей';
      else gen = st + 'ов';
      const soft = w.endsWith('и') && HUSH.indexOf(last(st)) < 0 && !/[гкх]$/.test(st);
      pl = { nom:lemma, gen, dat: st + (soft ? 'ям' : 'ам'), acc: lemma, ins: st + (soft ? 'ями' : 'ами'), pre: st + (soft ? 'ях' : 'ах') };
      res.sg = null; res.pl = pl; res.pluralOnly = true;
      notes.push('Chỉ dùng ở số nhiều (pluralia tantum).');
      return res;
    }
    /* ---- giống đực, tận cùng phụ âm / -й / -ь ---- */
    if (g === 'm' && !endsWith(w, 'а', 'я')){
      let stem, soft = false, iSoft = false; // iSoft: -ий (гений)
      if (w.endsWith('й')){ stem = w.slice(0, -1); soft = true; iSoft = w.endsWith('ий'); }
      else if (w.endsWith('ь')){ stem = w.slice(0, -1); soft = true; }
      else stem = w;
      // nguyên âm lướt
      let ob = dropFleeting(soft ? w.slice(0, -1) : w);
      if (ob == null) ob = stem;
      if (soft && ob === w.slice(0, -1)) ob = stem;
      if (w.endsWith('ей') && /^(воробей|соловей|муравей|ручей|улей)$/.test(w)){ ob = w.slice(0, -2) + 'ь'; soft = true; }
      const endStress = soft ? END_STRESS_SOFT.has(w) : stressOnEnd && (vowels(w) === 1 ? !/^(муж|душ|туш|марш|матч|скотч|кэш|плащ|борщ)$/.test(w) || /^(врач|нож|ключ|плащ|борщ|мяч|луч|меч|ёж|уж|грач|ткач|сыч|хрящ|клещ|лещ|плющ|прыщ|чиж|стриж|ёрш|ковш)$/.test(w) : /^(этаж|гараж|багаж|тираж|монтаж|вираж|карандаш|шалаш|малыш|камыш|рубеж|падеж|кирпич|калач|москвич|трубач|силач|богач|чертёж|платёж|отец|конец|продавец|молодец|купец|певец|боец|жилец|кузнец|беглец|лжец|глупец|творец|дворец|венец|огурец|борец|пловец|гонец|наглец|мудрец|храбрец|скворец|образец|близнец|беженец|юнец|ларец|мертвец|подлец|сорванец|стрелец|удалец|храбрец|чернец|пришелец)$/.test(w));
      const hushC = HUSH.indexOf(last(ob)) >= 0 || last(ob) === 'ц';
      const genE = soft ? 'я' : 'а', datE = soft ? 'ю' : 'у';
      const insE = soft ? (endStress ? 'ём' : 'ем') : (hushC ? (endStress ? 'ом' : 'ем') : 'ом');
      const preE = iSoft ? 'и' : 'е';
      sg.nom = lemma;
      sg.gen = K(ob + genE); sg.dat = K(ob + datE); sg.ins = K(ob + insE); sg.pre = K(ob + preE);
      sg.acc = anim ? sg.gen : lemma;
      // số nhiều
      let plNom;
      if (PL_YA[w]) plNom = PL_YA[w];
      else if (PL_A.has(w)) plNom = putStress(ob + (soft ? 'я' : 'а'), vowels(ob)); // города́, учителя́
      else if (soft) plNom = K(ob + 'и');
      else if (HUSH.indexOf(last(ob)) >= 0 || /[гкх]$/.test(ob)) plNom = K(ob + 'и');
      else plNom = K(ob + 'ы');
      const plStem = strip(plNom).replace(/[ыиая]$/, '');
      let plGen;
      if (PL_YA[w]) plGen = strip(plNom).endsWith('ья') ? (/^(князь|зять|кум|шурин|сын|муж|друг)$/.test(w) ? plStem + 'ей' : plStem + 'ев') : plStem + 'ев';
      else if (ZERO_GEN_PL.has(w)) plGen = ob;
      else if (soft) plGen = iSoft ? ob + 'ев' : (w.endsWith('й') ? ob + (endStress ? 'ёв' : 'ев') : ob + 'ей');
      else if (HUSH.indexOf(last(ob)) >= 0) plGen = ob + 'ей';
      else if (last(ob) === 'ц') plGen = ob + (endStress ? 'ов' : 'ев');
      else plGen = ob + 'ов';
      const plSoft = PL_YA[w] ? true : soft;
      const ya = plSoft && !(HUSH.indexOf(last(plStem)) >= 0);
      const plA = PL_A.has(w);
      const sufDat = ya ? 'ям' : 'ам', sufIns = ya ? 'ями' : 'ами', sufPre = ya ? 'ях' : 'ах';
      pl.nom = plNom;
      pl.gen = PL_YA[w] ? K(plGen) : (plA ? putStress(plGen, vowels(ob)) : K(plGen));
      pl.dat = plA ? putStress(plStem + sufDat, vowels(ob)) : (PL_YA[w] ? keep(plNom, plStem + sufDat) : K(plStem + sufDat));
      pl.ins = plA ? putStress(plStem + sufIns, vowels(ob)) : (PL_YA[w] ? keep(plNom, plStem + sufIns) : K(plStem + sufIns));
      pl.pre = plA ? putStress(plStem + sufPre, vowels(ob)) : (PL_YA[w] ? keep(plNom, plStem + sufPre) : K(plStem + sufPre));
      pl.acc = anim ? pl.gen : pl.nom;
      if (PL_YA[w] && /^(сын|муж|друг|князь|зять)$/.test(w)){ pl.gen = plStem + 'е́й'; pl.dat = plStem + 'я́м'; pl.ins = plStem + 'я́ми'; pl.pre = plStem + 'я́х'; pl.acc = pl.gen; }
      res.sg = sg; res.pl = pl;
      if (!keepS) notes.push('Trọng âm có thể chuyển sang đuôi khi biến cách (стол → стола́); bảng không ghi trọng âm.');
      return res;
    }
    /* ---- giống cái / đực tận cùng -а/-я ---- */
    if (endsWith(w, 'а', 'я')){
      const ya = w.endsWith('я'), stem = w.slice(0, -1), iya = w.endsWith('ия'), yaV = ya && isV(last(stem)) && !iya, ySoft = ya && last(stem) === 'ь';
      const hushC = HUSH.indexOf(last(stem)) >= 0 || last(stem) === 'ц';
      const velar = /[гкх]$/.test(stem);
      const endS = stressOnEnd && vowels(w) >= 2 && !keepS;
      const E = f => endS ? putS(f, vowels(stem)) : K(f);   // семьи́, семье́…
      sg.nom = lemma;
      sg.gen = E(stem + (ya || velar || HUSH.indexOf(last(stem)) >= 0 ? 'и' : 'ы'));
      sg.dat = E(stem + (iya ? 'и' : 'е'));
      sg.acc = E(stem + (ya ? 'ю' : 'у'));
      if (endS && ACC_SHIFT.has(w)) sg.acc = putS(stem + (ya ? 'ю' : 'у'), 0);
      if (ya) sg.ins = E(stem + (stressOnEnd ? 'ёй' : 'ей'));
      else sg.ins = E(stem + (hushC ? (stressOnEnd ? 'ой' : 'ей') : 'ой'));
      sg.pre = E(stem + (iya ? 'и' : 'е'));
      // số nhiều
      const plNom = K(stem + (ya || velar || HUSH.indexOf(last(stem)) >= 0 ? 'и' : 'ы'));
      let plGen;
      if (GEN_PL_F[w]) plGen = GEN_PL_F[w];
      else if (iya) plGen = K(stem.slice(0, -1) + 'ий');
      else if (ySoft) plGen = K(stem.slice(0, -1) + 'ей');
      else if (yaV) plGen = K(stem + 'й');
      else if (ya) plGen = K(last(stem) === 'н' && !isV(stem[stem.length - 2]) ? stem.slice(0, -1) + 'ен' : stem + 'ь');
      else plGen = K(genPlZeroFix(stem));
      const softPl = ya && !ySoft;
      const sufDat = softPl ? 'ям' : 'ам', sufIns = softPl ? 'ями' : 'ами', sufPre = softPl ? 'ях' : 'ах';
      pl.nom = plNom; pl.gen = plGen;
      pl.dat = K(stem + sufDat); pl.ins = K(stem + sufIns); pl.pre = K(stem + sufPre);
      if (ySoft){ pl.dat = K(stem + 'ям'); pl.ins = K(stem + 'ями'); pl.pre = K(stem + 'ях'); }
      pl.acc = anim ? pl.gen : pl.nom;
      res.sg = sg; res.pl = pl;
      if (!keepS) notes.push('Trọng âm ở đuôi (-а́) thường chuyển lên thân ở số nhiều (рука́ → ру́ки); bảng không ghi trọng âm.');
      return res;
    }
    /* ---- giống cái -ь ---- */
    if (g === 'f' && w.endsWith('ь')){
      const stem = w.slice(0, -1), hushC = HUSH.indexOf(last(stem)) >= 0;
      const KS = f => keep(lemma, f);
      sg.nom = lemma; sg.gen = KS(stem + 'и'); sg.dat = KS(stem + 'и'); sg.acc = lemma; sg.ins = KS(stem + 'ью'); sg.pre = KS(stem + 'и');
      if (w === 'любовь'){ sg.gen = sg.dat = sg.pre = 'любви́'; }
      pl.nom = KS(stem + 'и');
      pl.gen = GEN_PL_F[w] || (keepS && vowels(w) >= 2 ? K(stem + 'ей') : stem + 'ей');
      const a = hushC;
      const mobile = vowels(w) === 1 || /^(площадь|лошадь|скорость|новость|часть|дверь|сеть|степь|кость|честь|соль|ночь|речь|печь|тень|цепь|ось|власть|область|очередь|смерть|весть|мать|дочь|церковь|ель|мель|моль|пыль|бровь|ладонь|ступень|степень|плоскость|мелочь|вещь|мышь|горсть|четверть|ткань|грудь|кровь|шерсть|лошадь|скатерть)$/.test(w);
      pl.dat = mobile ? stem + (a ? 'ам' : 'ям') : K(stem + (a ? 'ам' : 'ям'));
      pl.ins = mobile ? stem + (a ? 'ами' : 'ями') : K(stem + (a ? 'ами' : 'ями'));
      pl.pre = mobile ? stem + (a ? 'ах' : 'ях') : K(stem + (a ? 'ах' : 'ях'));
      if (mobile) pl.gen = GEN_PL_F[w] || (stem + 'ей');
      pl.acc = anim ? pl.gen : pl.nom;
      res.sg = sg; res.pl = pl;
      if (mobile) notes.push('Ở số nhiều (cách 2, 3, 5, 6) trọng âm thường chuyển sang đuôi: ночь → ноче́й, ноча́м.');
      return res;
    }
    /* ---- giống trung -о/-е/-ё/-мя ---- */
    if (g === 'n'){
      if (w.endsWith('мя')){ const st = w.slice(0, -1) + 'ен'; sg = { nom:lemma, gen:K(st + 'и'), dat:K(st + 'и'), acc:lemma, ins:K(st + 'ем'), pre:K(st + 'и') }; pl = { nom:st + 'а́', gen:st.slice(0,-2) + 'ён', dat:st + 'а́м', acc:st + 'а́', ins:st + 'а́ми', pre:st + 'а́х' }; res.sg = sg; res.pl = pl; return res; }
      const stem = w.slice(0, -1), ie = w.endsWith('ие'), ye = w.endsWith('ье'), hushC = HUSH.indexOf(last(stem)) >= 0 || last(stem) === 'ц';
      const e = (w.endsWith('е') || w.endsWith('ё')) && !hushC;
      const endN = stressOnEnd && vowels(w) >= 2;
      const NS = f => endN ? putS(f, vowels(stem)) : keep(lemma, f);
      sg.nom = lemma;
      sg.gen = NS(stem + (e ? 'я' : 'а')); sg.dat = NS(stem + (e ? 'ю' : 'у')); sg.acc = lemma;
      sg.ins = NS(stem + (e ? (w.endsWith('ё') ? 'ём' : 'ем') : (hushC ? (stressOnEnd ? 'ом' : 'ем') : 'ом')));
      if (hushC && (w.endsWith('е') || w.endsWith('ё'))) sg.ins = NS(stem + (stressOnEnd ? 'ом' : 'ем'));
      sg.pre = NS(stem + (ie ? 'и' : 'е'));
      // số nhiều
      let plNom, plGen;
      const two = (vowels(w) === 2 || /^(зеркало|облако|войско|кружево|зарево|озеро|дерево|болото2)$/.test(w)) && !NEUT_FIXED.has(w) && !ie && !ye && !endsWith(w, 'ство');
      const shiftPl = two; // ме́сто → места́, окно́ → о́кна
      if (e) plNom = stem + 'я';
      else plNom = stem + 'а';
      if (ie) plGen = stem.slice(0, -1) + 'ий';
      else if (ye) plGen = stem.slice(0, -1) + (/^(платье|устье|верховье|низовье|подмастерье|ущелье2)$/.test(w) ? 'ьев' : 'ий');
      else if (w === 'солнце') plGen = 'солнц';
      else if (e && !hushC) plGen = stem + 'ей';
      else plGen = genPlZeroFix(stem);
      if (w === 'море' || w === 'поле') plGen = stem + 'ей';
      const softPl = e && !hushC;
      const sufDat = softPl ? 'ям' : 'ам', sufIns = softPl ? 'ями' : 'ами', sufPre = softPl ? 'ях' : 'ах';
      if (shiftPl){
        const endIdx = stressOnEnd; // окно́ → о́кна (trọng âm về thân); ме́сто → места́ (về đuôi)
        const put = (f, toEnd) => putStress(f, toEnd ? vowels(stem) : 0);
        pl.nom = put(plNom, !endIdx); pl.gen = endIdx ? putStress(plGen, 0) : putStress(plGen, Math.max(0, vowels(plGen) - 1));
        pl.dat = put(stem + sufDat, !endIdx); pl.ins = put(stem + sufIns, !endIdx); pl.pre = put(stem + sufPre, !endIdx);
        if (!endIdx && vowels(plGen) >= 2) pl.gen = putStress(plGen, vowels(plGen) - 1); // мест → мест; дел → дел (1 nguyên âm)
        if (vowels(plGen) === 1) pl.gen = plGen;
        notes.push('Danh từ giống trung 2 âm tiết: trọng âm chuyển khi sang số nhiều (ме́сто → места́, окно́ → о́кна).');
      } else {
        const KP = f => (!stressOnEnd && stressIdx(lemma) >= 0) ? keep(lemma, f) : f;
        pl.nom = KP(plNom); pl.gen = KP(plGen); pl.dat = KP(stem + sufDat); pl.ins = KP(stem + sufIns); pl.pre = KP(stem + sufPre);
      }
      pl.acc = pl.nom;
      res.sg = sg; res.pl = pl;
      return res;
    }
    return res;
  }

