  const CMP_IRR = { 'хороший':'лу́чше','плохой':'ху́же','большой':'бо́льше','маленький':'ме́ньше','старый':'ста́рше','молодой':'моло́же','дорогой':'доро́же','дешёвый':'деше́вле','высокий':'вы́ше','низкий':'ни́же','широкий':'ши́ре','узкий':'у́же','далёкий':'да́льше','долгий':'до́льше','глубокий':'глу́бже','мелкий':'ме́льче','сладкий':'сла́ще','редкий':'ре́же','мягкий':'мя́гче','громкий':'гро́мче','тихий':'ти́ше','крепкий':'кре́пче','яркий':'я́рче','жаркий':'жа́рче','лёгкий':'ле́гче','короткий':'коро́че','близкий':'бли́же','гладкий':'гла́же','поздний':'по́зже','ранний':'ра́ньше','тонкий':'то́ньше','горький':'го́рче','сухой':'су́ше','строгий':'стро́же','крутой':'кру́че','частый':'ча́ще','густой':'гу́ще','твёрдый':'твёрже','простой':'про́ще','чистый':'чи́ще','толстый':'то́лще','богатый':'бога́че','дикий':'ди́че','жидкий':'жи́же','сладкий':'сла́ще','лёгкий':'ле́гче','плоский':'пло́ще','звонкий':'зво́нче','мелкий':'ме́льче','злой':'зле́е','новый':'нове́е' };
  function adj(lemma){
    const w = strip(lemma).toLowerCase();
    const res = { lemma, m:{}, f:{}, n:{}, pl:{}, short:null, cmp:null, notes:[] };
    let stem, type; // hard | soft | velar | hush
    if (endsWith(w, 'ый', 'ой')){ stem = w.slice(0, -2); type = /[гкх]$/.test(stem) ? 'velar' : (HUSH.indexOf(last(stem)) >= 0 ? 'hush' : 'hard'); }
    else if (w.endsWith('ий')){ stem = w.slice(0, -2); type = /[гкх]$/.test(stem) ? 'velar' : (HUSH.indexOf(last(stem)) >= 0 ? 'hush' : 'soft'); }
    else return null;
    const endStress = w.endsWith('ой');
    const K = f => keep(lemma, f);
    const o = ((type === 'hush' && !endStress) || type === 'soft') ? 'е' : 'о'; // хорошего / большого / синего
    const i = (type === 'hard') ? 'ы' : 'и';
    const yaya = type === 'soft';
    res.m = { nom:lemma, gen:K(stem + o + 'го'), dat:K(stem + o + 'му'), accI:lemma, accA:K(stem + o + 'го'), ins:K(stem + i + 'м'), pre:K(stem + o + 'м') };
    res.f = { nom:K(stem + (yaya ? 'яя' : 'ая')), gen:K(stem + (yaya || (type === 'hush' && !endStress) ? 'ей' : 'ой')), dat:K(stem + (yaya || (type === 'hush' && !endStress) ? 'ей' : 'ой')), acc:K(stem + (yaya ? 'юю' : 'ую')), ins:K(stem + (yaya || (type === 'hush' && !endStress) ? 'ей' : 'ой')), pre:K(stem + (yaya || (type === 'hush' && !endStress) ? 'ей' : 'ой')) };
    res.n = { nom:K(stem + (yaya || (type === 'hush' && !endStress) ? 'ее' : 'ое')), gen:res.m.gen, dat:res.m.dat, acc:K(stem + (yaya || (type === 'hush' && !endStress) ? 'ее' : 'ое')), ins:res.m.ins, pre:res.m.pre };
    res.pl = { nom:K(stem + i + 'е'), gen:K(stem + i + 'х'), dat:K(stem + i + 'м'), accI:K(stem + i + 'е'), accA:K(stem + i + 'х'), ins:K(stem + i + 'ми'), pre:K(stem + i + 'х') };
    // dạng ngắn
    if (ADJ_IRR_SHORT[w]) res.short = ADJ_IRR_SHORT[w];
    else if (!endsWith(w, 'ский', 'ний', 'цкий', 'ский') && !/(ов|ев|ин)ый$/.test(w) && !endsWith(w, 'ший', 'щий', 'ущий', 'ющий') && type !== 'soft'){
      let m = stem;
      const c1 = stem[stem.length - 2], c2 = last(stem);
      if (!isV(c1) && c2 === 'н' && c1 !== 'й') m = stem.slice(0, -1) + 'ен';
      else if (c1 === 'й' && c2 === 'н') m = stem.slice(0, -2) + 'ен';
      else if (!isV(c1) && c2 === 'к' && c1 !== 'ь') m = stem.slice(0, -1) + 'ок';
      else if (c1 === 'ь' && c2 === 'к') m = stem.slice(0, -2) + 'ек';
      else if (!isV(c1) && (c2 === 'л' || c2 === 'р') && c1 !== 'ь') m = stem.slice(0, -1) + 'е' + c2;
      const f = stem + 'а', n = stem + 'о', pl = stem + i;
      res.short = [K(m), K(f), K(n), K(pl)];
      res.notes.push('Dạng ngắn tạo tự động theo quy tắc; trọng âm dạng ngắn có thể đổi (nếu chưa chắc, tra Wiktionary).');
    }
    // so sánh hơn
    if (CMP_IRR[w]) res.cmp = CMP_IRR[w];
    else if (type === 'soft' && endsWith(w, 'ний')) res.cmp = null;
    else if (!endsWith(w, 'ский', 'цкий') && !/(ов|ев|ин)ый$/.test(w) && !endsWith(w, 'ший', 'щий')){
      if (/[гкх]$/.test(stem)) res.cmp = stem.slice(0, -1) + ({ 'г':'ж', 'к':'ч', 'х':'ш' }[last(stem)]) + 'е';
      else res.cmp = vowels(stem) === 1 ? stem.replace(/ё/g, 'е') + 'е́е' : K(stem + 'ее');
      if (/^(частый|густой|твёрдый|крутой|молодой|богатый|простой|чистый|толстый)$/.test(w)) res.cmp = CMP_IRR[w];
    }
    return res;
  }

